import"./chunk-VC46IEJQ.js";var a=([t,o])=>({en:t,zh:o}),e=(t,o,r,n,i,h,d,l,s)=>({name:a(t),desc:a(o),tour:a(r),...s?{spoiler:a(s)}:{},source:{confidence:n,refs:i,book:a(h),unknown:a(d),interpretation:a(l)}}),w={id:"highgarden",intro:{en:"Highgarden is the seat of House Tyrell and the heart of the Reach, a fair castle on a hill above the Mander amid gardens, orchards and fields. No novel chapter is set there, so this sunny scene leans on the companion book and on interpretation.",zh:"\u9AD8\u5EAD\u662F\u63D0\u5229\u5C14\u5BB6\u65CF\u7684\u5C45\u57CE\u3001\u6CB3\u6E7E\u5730\u7684\u4E2D\u5FC3\uFF0C\u4E00\u5EA7\u79C0\u7F8E\u7684\u57CE\u5821\uFF0C\u5750\u843D\u5728\u66FC\u5FB7\u6CB3\u7554\u7684\u5C71\u4E18\u4E0A\uFF0C\u56DB\u5468\u82B1\u56ED\u3001\u679C\u56ED\u4E0E\u7530\u91CE\u73AF\u7ED5\u3002\u5C0F\u8BF4\u4E2D\u6CA1\u6709\u4E00\u7AE0\u53D1\u751F\u5728\u9AD8\u5EAD\uFF0C\u56E0\u6B64\u8FD9\u7247\u660E\u5A9A\u666F\u81F4\u4E3B\u8981\u4F9D\u636E\u8BBE\u5B9A\u96C6\u4E0E\u827A\u672F\u6F14\u7ECE\u3002"},notes:{en:"From the novels: the Tyrell seat on the Mander, great wealth, roses everywhere, the green banner with a golden rose. From The World of Ice & Fire, via wiki summaries: three rings of white stone walls rising in height, a briar maze between the outer and middle walls, and a godswood with three entwined weirwoods called the Three Singers. Invented: all plans, positions, proportions and colours, the keep, the sept and the town.",zh:"\u5C0F\u8BF4\u786E\u7ACB\uFF1A\u63D0\u5229\u5C14\u5BB6\u65CF\u636E\u66FC\u5FB7\u6CB3\u800C\u5C45\uFF0C\u5BCC\u7532\u4E00\u65B9\uFF0C\u5904\u5904\u73AB\u7470\uFF0C\u65D7\u5E1C\u4E3A\u7EFF\u5E95\u91D1\u73AB\u7470\u3002\u636E\u7EF4\u57FA\u6458\u8981\uFF0C\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\uFF1A\u4E16\u754C\u300B\u8865\u5145\u4E86\uFF1A\u4E09\u5708\u9010\u5C42\u5347\u9AD8\u7684\u767D\u77F3\u57CE\u5899\uFF0C\u5916\u5899\u4E0E\u4E2D\u5899\u4E4B\u95F4\u7684\u8346\u68D8\u8FF7\u5BAB\uFF0C\u4EE5\u53CA\u795E\u6728\u6797\u4E2D\u4E09\u682A\u4EA4\u7F20\u800C\u751F\u3001\u540D\u4E3A\u201C\u4E09\u6B4C\u624B\u201D\u7684\u9C7C\u6881\u6728\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5168\u90E8\u5E03\u5C40\u3001\u4F4D\u7F6E\u3001\u6BD4\u4F8B\u4E0E\u8272\u5F69\uFF0C\u4EE5\u53CA\u4E3B\u5821\u3001\u5723\u5802\u4E0E\u57CE\u9547\u3002"},tour:["the-hill-and-road","concentric-walls","hedge-maze","tyrell-keep","rose-gardens","castle-sept","godswood","highgarden-town","orchards","mander"],sources:[{ref:"asos",checked:"memory",note:{en:"Highgarden is evoked by the Tyrells in Sansa's chapters in King's Landing; it is never visited on-page. Recalled, not re-read.",zh:"\u9AD8\u5EAD\u53EA\u5728\u73CA\u838E\u4E8E\u541B\u4E34\u7684\u7AE0\u8282\u4E2D\u7ECF\u63D0\u5229\u5C14\u5BB6\u4EBA\u4E4B\u53E3\u63CF\u7ED8\uFF0C\u4E66\u4E2D\u4ECE\u672A\u6709\u573A\u666F\u53D1\u751F\u5728\u90A3\u91CC\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"The three wall rings, the briar maze and the Three Singers are attributed to the companion book by wiki summaries; the book itself was not consulted.",zh:"\u4E09\u5708\u57CE\u5899\u3001\u8346\u68D8\u8FF7\u5BAB\u4E0E\u201C\u4E09\u6B4C\u624B\u201D\uFF0C\u636E\u7EF4\u57FA\u6458\u8981\u51FA\u81EA\u8BBE\u5B9A\u96C6\uFF1B\u539F\u4E66\u672A\u67E5\u9605\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Wiki summaries of Highgarden and its godswood; pages not fetched.",zh:"\u9AD8\u5EAD\u53CA\u5176\u795E\u6728\u6797\u7684\u7EF4\u57FA\u6458\u8981\uFF1B\u9875\u9762\u672A\u6293\u53D6\u3002"}}],landmarks:{"tyrell-keep":e(["Tyrell Keep","\u63D0\u5229\u5C14\u4E3B\u5821"],["A grand, pale keep with colonnades, slender towers and climbing roses, crowned by a golden dome.","\u5B8F\u4F1F\u7684\u6D45\u8272\u4E3B\u5821\uFF0C\u7ACB\u67F1\u56DE\u5ECA\u3001\u7EC6\u9AD8\u5854\u697C\uFF0C\u5899\u4E0A\u6500\u6EE1\u73AB\u7470\uFF0C\u9876\u8986\u91D1\u8272\u7A79\u9876\u3002"],["The Tyrells live in a palace as much as a fortress.","\u63D0\u5229\u5C14\u5BB6\u65CF\u7684\u5C45\u6240\uFF0C\u65E2\u662F\u8981\u585E\uFF0C\u66F4\u50CF\u5BAB\u6BBF\u3002"],"low",["asos","twoiaf"],["Highgarden is renowned as one of the most beautiful castles in Westeros; its keep is not described in the novels.","\u9AD8\u5EAD\u4EE5\u7EF4\u65AF\u7279\u6D1B\u6700\u7F8E\u7684\u57CE\u5821\u4E4B\u4E00\u8457\u79F0\uFF1B\u5C0F\u8BF4\u672A\u63CF\u5199\u5176\u4E3B\u5821\u3002"],["Floor plan, height, materials and form.","\u5E73\u9762\u3001\u9AD8\u5EA6\u3001\u77F3\u6599\u4E0E\u5F62\u5236\u3002"],["A broad colonnaded block with five tall round towers and a golden-domed hall.","\u5BBD\u9614\u7684\u67F1\u5ECA\u4E3B\u697C\uFF0C\u914D\u4E94\u5EA7\u9AD8\u5706\u5854\u4E0E\u91D1\u9876\u5927\u5385\u3002"]),"concentric-walls":e(["Three Walls","\u4E09\u91CD\u57CE\u5899"],["Three rings of white wall climb the hill, each higher than the last, their gates staggered so the road winds.","\u4E09\u5708\u767D\u5899\u5C42\u5C42\u6500\u4E0A\u5C71\u4E18\uFF0C\u4E00\u5708\u9AD8\u8FC7\u4E00\u5708\uFF0C\u57CE\u95E8\u9519\u5F00\uFF0C\u9053\u8DEF\u873F\u8712\u800C\u4E0A\u3002"],["Three rings of white stone, each taller than the one outside it.","\u4E09\u5708\u767D\u77F3\u57CE\u5899\uFF0C\u4E00\u5708\u6BD4\u4E00\u5708\u9AD8\u3002"],"medium",["twoiaf","awoiaf"],["The companion book gives Highgarden three concentric rings of white stone walls, increasing in height.","\u8BBE\u5B9A\u96C6\u79F0\u9AD8\u5EAD\u6709\u4E09\u5708\u540C\u5FC3\u767D\u77F3\u57CE\u5899\uFF0C\u7531\u5916\u5411\u5185\u9010\u5C42\u5347\u9AD8\u3002"],["Height, gate arrangement and the area enclosed.","\u57CE\u5899\u9AD8\u5EA6\u3001\u57CE\u95E8\u5E03\u7F6E\u4E0E\u56F4\u5408\u9762\u79EF\u3002"],["Three rings with towers and staggered gates; all geometry invented.","\u4E09\u5708\u57CE\u5899\uFF0C\u914D\u5854\u697C\u4E0E\u9519\u4F4D\u57CE\u95E8\uFF1B\u51E0\u4F55\u5F62\u6001\u5747\u4E3A\u81EA\u62DF\u3002"]),"rose-gardens":e(["Rose Gardens","\u73AB\u7470\u82B1\u56ED"],["Terraced beds of pink, red and white roses fill the wards between keep and walls.","\u7C89\u3001\u7EA2\u3001\u767D\u4E09\u8272\u73AB\u7470\u82B1\u5703\u5C42\u5C42\u94FA\u5F00\uFF0C\u586B\u6EE1\u4E3B\u5821\u4E0E\u57CE\u5899\u4E4B\u95F4\u7684\u5EAD\u9662\u3002"],["The Tyrell sigil is a golden rose on green; here roses grow everywhere.","\u63D0\u5229\u5C14\u5BB6\u65CF\u7684\u7EB9\u7AE0\u662F\u7EFF\u5E95\u91D1\u73AB\u7470\uFF1B\u5728\u8FD9\u91CC\uFF0C\u73AB\u7470\u904D\u5730\u76DB\u5F00\u3002"],"medium",["asos","twoiaf"],["Gardens and roses are the hallmark of the Tyrells, and the castle's name.","\u82B1\u56ED\u4E0E\u73AB\u7470\u662F\u63D0\u5229\u5C14\u5BB6\u65CF\u7684\u6807\u5FD7\uFF0C\u4E5F\u662F\u57CE\u5821\u540D\u5B57\u7684\u7531\u6765\u3002"],["Their layout and the plants grown.","\u82B1\u56ED\u5E03\u5C40\u4E0E\u79CD\u690D\u54C1\u79CD\u3002"],["Hundreds of coloured beds scattered across the middle ward.","\u4E2D\u5EAD\u91CC\u6563\u5E03\u7740\u6570\u767E\u5757\u5F69\u8272\u82B1\u5703\u3002"]),"hedge-maze":e(["Briar Maze","\u8346\u68D8\u8FF7\u5BAB"],["A ring of hedges between the outer and middle walls that amuses guests and slows intruders.","\u5916\u5899\u4E0E\u4E2D\u5899\u4E4B\u95F4\u7684\u4E00\u5708\u6811\u7BF1\u8FF7\u5BAB\uFF0C\u65E2\u4F9B\u5BBE\u5BA2\u6D88\u9063\uFF0C\u4E5F\u80FD\u62D6\u4F4F\u5165\u4FB5\u8005\u3002"],["Between the outer and middle walls winds a famous briar maze.","\u5916\u5899\u4E0E\u4E2D\u5899\u4E4B\u95F4\uFF0C\u873F\u8712\u7740\u4E00\u5EA7\u8457\u540D\u7684\u8346\u68D8\u8FF7\u5BAB\u3002"],"medium",["twoiaf","awoiaf"],["The companion book describes a briar labyrinth between the outer and middle walls, for amusement and defence alike.","\u8BBE\u5B9A\u96C6\u8BB0\u8F7D\u5916\u5899\u4E0E\u4E2D\u5899\u4E4B\u95F4\u6709\u4E00\u5EA7\u8346\u68D8\u8FF7\u5BAB\uFF0C\u517C\u5177\u6E38\u4E50\u4E0E\u9632\u5FA1\u4E4B\u7528\u3002"],["Its size and pattern.","\u8FF7\u5BAB\u7684\u89C4\u6A21\u4E0E\u56FE\u6837\u3002"],["Four concentric hedge rings with random gaps; not a solvable plan.","\u56DB\u5708\u5E26\u968F\u673A\u7F3A\u53E3\u7684\u540C\u5FC3\u6811\u7BF1\uFF1B\u5E76\u975E\u53EF\u89E3\u7684\u771F\u5B9E\u8FF7\u5BAB\u3002"]),"castle-sept":e(["Castle Sept","\u57CE\u5185\u5723\u5802"],["A small sept with stained-glass windows in the inner ward, where the Tyrells honour the Seven.","\u5185\u5EAD\u4E2D\u7684\u5C0F\u5723\u5802\uFF0C\u5F69\u7A97\u6591\u6593\uFF0C\u63D0\u5229\u5C14\u5BB6\u65CF\u5728\u6B64\u656C\u5949\u4E03\u795E\u3002"],["Coloured glass catches the sun in the Tyrells' own sept.","\u5F69\u8272\u73BB\u7483\u6620\u7740\u9633\u5149\uFF0C\u8FD9\u662F\u63D0\u5229\u5C14\u5BB6\u65CF\u81EA\u5DF1\u7684\u5723\u5802\u3002"],"low",["awoiaf"],["The Tyrells keep the Faith of the Seven; a castle sept is attributed only by wiki summaries.","\u63D0\u5229\u5C14\u5BB6\u65CF\u4FE1\u5949\u4E03\u795E\uFF1B\u57CE\u5185\u5723\u5802\u4EC5\u89C1\u4E8E\u7EF4\u57FA\u6458\u8981\u3002"],["Whether it exists, its size and location.","\u662F\u5426\u5B58\u5728\uFF0C\u4EE5\u53CA\u89C4\u6A21\u4E0E\u4F4D\u7F6E\u3002"],["A small hall with a spire and five coloured windows.","\u5E26\u5C16\u5854\u4E0E\u4E94\u6247\u5F69\u7A97\u7684\u5C0F\u6BBF\u3002"]),godswood:e(["Godswood","\u795E\u6728\u6797"],["A grove around three ancient weirwoods so entwined they look like one tree, above a quiet pool.","\u4E00\u7247\u6797\u5730\uFF0C\u4E2D\u592E\u4E09\u682A\u53E4\u8001\u7684\u9C7C\u6881\u6728\u679D\u5E72\u4EA4\u7F20\uFF0C\u5B9B\u5982\u4E00\u6811\u4E09\u5E72\uFF0C\u6811\u4E0B\u4E00\u6C6A\u9759\u6C34\u3002"],["The Three Singers: three weirwoods grown together into one.","\u201C\u4E09\u6B4C\u624B\u201D\uFF1A\u4E09\u682A\u9C7C\u6881\u6728\u4EA4\u7F20\u751F\u957F\uFF0C\u5408\u800C\u4E3A\u4E00\u3002"],"medium",["twoiaf","awoiaf"],["The companion book describes three entwined weirwoods, the Three Singers, over a pool in Highgarden's godswood.","\u8BBE\u5B9A\u96C6\u8BB0\u8F7D\u9AD8\u5EAD\u795E\u6728\u6797\u4E2D\u6709\u4E09\u682A\u4EA4\u7F20\u7684\u9C7C\u6881\u6728\uFF0C\u540D\u4E3A\u201C\u4E09\u6B4C\u624B\u201D\uFF0C\u6811\u4E0B\u6709\u6C60\u3002"],["The grove's size and its position in the castle.","\u6797\u5730\u7684\u5927\u5C0F\u53CA\u5728\u57CE\u4E2D\u7684\u4F4D\u7F6E\u3002"],["A small oak grove with three white-trunked trees.","\u4E00\u5C0F\u7247\u6A61\u6811\u6797\uFF0C\u914D\u4E09\u682A\u767D\u5E72\u6811\u3002"]),mander:e(["The Mander","\u66FC\u5FB7\u6CB3"],["A broad, slow river winding below the hill, carrying barges and watering the richest farmland in the realm.","\u5BBD\u9614\u8212\u7F13\u7684\u6CB3\u6D41\u7ED5\u8FC7\u5C71\u811A\uFF0C\u8F7D\u7740\u9A73\u8239\uFF0C\u704C\u6E89\u738B\u56FD\u6700\u80A5\u6C83\u7684\u7530\u5730\u3002"],["The Mander waters the Reach and carries its trade to the sea.","\u66FC\u5FB7\u6CB3\u704C\u6E89\u6CB3\u6E7E\u5730\uFF0C\u5E76\u5C06\u5546\u8D27\u8FD0\u5F80\u5927\u6D77\u3002"],"high",["asos","twoiaf","maps"],["Highgarden stands on the Mander in the Reach.","\u9AD8\u5EAD\u4F4D\u4E8E\u6CB3\u6E7E\u5730\u7684\u66FC\u5FB7\u6CB3\u7554\u3002"],["The river's exact course by the castle.","\u57CE\u5821\u9644\u8FD1\u7684\u786E\u5207\u6CB3\u9053\u3002"],["A winding channel south of the hill with a stone bridge and a few barges.","\u5C71\u4E18\u5357\u4FA7\u7684\u873F\u8712\u6CB3\u9053\uFF0C\u8BBE\u4E00\u5EA7\u77F3\u6865\u4E0E\u51E0\u8258\u9A73\u8239\u3002"]),orchards:e(["Orchards","\u679C\u56ED"],["Ordered rows of fruit trees and ripe fields stretch across the fertile Reach.","\u6210\u884C\u7684\u679C\u6811\u4E0E\u6210\u719F\u7684\u7530\u91CE\u5411\u6CB3\u6E7E\u5730\u7684\u6C83\u571F\u5EF6\u5C55\u3002"],["The Reach is the realm's larder: fruit, grain and wine.","\u6CB3\u6E7E\u5730\u662F\u738B\u56FD\u7684\u7CAE\u4ED3\uFF1A\u6C34\u679C\u3001\u8C37\u7269\u4E0E\u7F8E\u9152\u3002"],"medium",["asos","twoiaf"],["The Reach is the most fertile region of Westeros, famed for its harvests, fruit and wine.","\u6CB3\u6E7E\u5730\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u80A5\u6C83\u7684\u5730\u533A\uFF0C\u4EE5\u4E30\u6536\u3001\u6C34\u679C\u4E0E\u7F8E\u9152\u95FB\u540D\u3002"],["Where orchards lie relative to the castle.","\u679C\u56ED\u4E0E\u57CE\u5821\u7684\u76F8\u5BF9\u4F4D\u7F6E\u3002"],["Regular orchard blocks of low trees as stand-ins.","\u4EE5\u4F4E\u77EE\u6811\u6728\u6392\u6210\u6574\u9F50\u7684\u679C\u56ED\u65B9\u5757\u793A\u610F\u3002"]),"highgarden-town":e(["Highgarden Town","\u9AD8\u5EAD\u9547"],["A modest market town of whitewashed houses with sage and terracotta roofs below the castle hill.","\u5C71\u811A\u4E0B\u7684\u5C0F\u96C6\u9547\uFF0C\u767D\u5899\u623F\u5C4B\u914D\u7070\u7EFF\u4E0E\u8D64\u9676\u5C4B\u9876\u3002"],["Merchants and farmers gather at the foot of the hill.","\u5546\u4EBA\u4E0E\u519C\u4EBA\u5728\u5C71\u811A\u4E0B\u805A\u96C6\u3002"],"low",["twoiaf"],["Nothing specific; no town at Highgarden is described in the novels.","\u65E0\u5177\u4F53\u8BB0\u8F7D\uFF1B\u5C0F\u8BF4\u4E2D\u672A\u63CF\u5199\u9AD8\u5EAD\u6709\u57CE\u9547\u3002"],["Whether a town exists, its size and layout.","\u662F\u5426\u6709\u57CE\u9547\uFF0C\u4EE5\u53CA\u89C4\u6A21\u4E0E\u5E03\u5C40\u3002"],["Scattered houses east of the hill; a placeholder.","\u5C71\u4E18\u4E1C\u4FA7\u7684\u96F6\u6563\u623F\u5C4B\uFF1B\u4EC5\u4F5C\u793A\u610F\u3002"]),"the-hill-and-road":e(["The Hill and Roads","\u5C71\u4E18\u4E0E\u5927\u9053"],["A broad green hill carries the castle; the Roseroad and the Ocean Road meet nearby.","\u5BBD\u9614\u7684\u9752\u7FE0\u5C71\u4E18\u6258\u8D77\u57CE\u5821\uFF1B\u73AB\u7470\u5927\u9053\u4E0E\u6D77\u6D0B\u5927\u9053\u5728\u9644\u8FD1\u4EA4\u6C47\u3002"],["Roads from across the Reach converge at the foot of the hill.","\u6CB3\u6E7E\u5730\u5404\u5904\u7684\u9053\u8DEF\u5728\u5C71\u811A\u6C47\u805A\u3002"],"medium",["maps","awoiaf"],["Published maps show the Roseroad running to Highgarden and the Ocean Road linking it with the west coast.","\u5DF2\u51FA\u7248\u7684\u5730\u56FE\u663E\u793A\uFF0C\u73AB\u7470\u5927\u9053\u901A\u5F80\u9AD8\u5EAD\uFF0C\u6D77\u6D0B\u5927\u9053\u5C06\u5B83\u4E0E\u897F\u6D77\u5CB8\u76F8\u8FDE\u3002"],["Exact road alignments and the hill's height.","\u9053\u8DEF\u7684\u786E\u5207\u8D70\u5411\u4E0E\u5C71\u4E18\u9AD8\u5EA6\u3002"],["A single winding road spiralling up the hill.","\u4E00\u6761\u873F\u8712\u5927\u9053\u76D8\u65CB\u4E0A\u5C71\u3002"])}};export{w as default};
